"""Exception hierarchy for microvm."""


class MicroVMError(Exception):
    """Base class of every error raised by microvm."""


class _OffsetError(MicroVMError):
    def __init__(self, message: str, offset: int) -> None:
        super().__init__(f"{message} (at offset {offset})")
        self.offset = offset


class LexError(_OffsetError):
    """Malformed token; carries a zero-based ``offset``."""


class ParseError(_OffsetError):
    """Malformed program; carries a zero-based ``offset``."""


class CompileError(MicroVMError):
    """Semantic error detected at compile time (undeclared / redeclared names)."""


class SerializationError(MicroVMError):
    """Malformed or unrepresentable binary program."""


class VMRuntimeError(MicroVMError):
    """Error raised while executing bytecode."""


class StepLimitError(VMRuntimeError):
    """The step budget was exceeded."""

"""Tokenizer for the microvm language."""

from __future__ import annotations

import dataclasses
import re

from .errors import LexError

KEYWORDS: frozenset[str] = frozenset(
    {"let", "print", "if", "else", "while", "true", "false", "and", "or", "not"}
)

# Longest operators first so that the alternation prefers "==" over "=".
_OPERATORS: tuple[str, ...] = (
    "==", "!=", "<=", ">=", "+", "-", "*", "/", "%", "(", ")", "{", "}", ";", "=", "<", ">",
)
_OP_RE = re.compile("|".join(re.escape(op) for op in _OPERATORS))
_IDENT_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")
# Floats are digits "." digits with an optional exponent; a bare exponent (1e3) or a
# dangling dot (1. / .5) is rejected by the number branch below.
_NUMBER_RE = re.compile(r"[0-9]+(\.[0-9]+([eE][+-]?[0-9]+)?)?")
_ESCAPES: dict[str, str] = {"n": "\n", "t": "\t", '"': '"', "\\": "\\"}


@dataclasses.dataclass(frozen=True)
class Token:
    kind: str
    text: str
    value: object
    offset: int


def _lex_number(src: str, pos: int) -> Token:
    match = _NUMBER_RE.match(src, pos)
    assert match is not None
    end = match.end()
    if end < len(src) and (src[end] == "." or src[end].isalpha() or src[end] == "_"):
        raise LexError("malformed number", pos)
    text = match.group(0)
    if match.group(1) is None:
        return Token("INT", text, int(text), pos)
    return Token("FLOAT", text, float(text), pos)


def _lex_string(src: str, pos: int) -> tuple[Token, int]:
    chars: list[str] = []
    i = pos + 1
    while True:
        if i >= len(src):
            raise LexError("unterminated string", pos)
        ch = src[i]
        if ch == '"':
            value = "".join(chars)
            return Token("STRING", value, value, pos), i + 1
        if ch == "\n":
            raise LexError("newline inside string", i)
        if ch == "\\":
            if i + 1 >= len(src):
                raise LexError("unterminated string", pos)
            esc = src[i + 1]
            if esc not in _ESCAPES:
                raise LexError(f"invalid escape sequence \\{esc}", i)
            chars.append(_ESCAPES[esc])
            i += 2
            continue
        chars.append(ch)
        i += 1


def tokenize(src: str) -> list[Token]:
    tokens: list[Token] = []
    pos = 0
    length = len(src)
    while pos < length:
        ch = src[pos]
        if ch.isspace():
            pos += 1
        elif src.startswith("//", pos):
            newline = src.find("\n", pos)
            pos = length if newline < 0 else newline + 1
        elif ch.isdigit():
            token = _lex_number(src, pos)
            tokens.append(token)
            pos += len(token.text)
        elif ch == '"':
            token, pos = _lex_string(src, pos)
            tokens.append(token)
        elif ch.isalpha() or ch == "_":
            match = _IDENT_RE.match(src, pos)
            assert match is not None
            text = match.group(0)
            kind = "KEYWORD" if text in KEYWORDS else "IDENT"
            tokens.append(Token(kind, text, text, pos))
            pos = match.end()
        else:
            match = _OP_RE.match(src, pos)
            if match is None:
                raise LexError(f"unexpected character {ch!r}", pos)
            text = match.group(0)
            tokens.append(Token("OP", text, text, pos))
            pos = match.end()
    return tokens

"""Recursive-descent parser producing a small dataclass-based AST."""

from __future__ import annotations

import dataclasses

from .errors import ParseError
from .lexer import Token, tokenize


@dataclasses.dataclass(frozen=True)
class Literal:
    value: object
    offset: int


@dataclasses.dataclass(frozen=True)
class Name:
    name: str
    offset: int


@dataclasses.dataclass(frozen=True)
class Unary:
    op: str  # "-" or "not"
    operand: object
    offset: int


@dataclasses.dataclass(frozen=True)
class Binary:
    op: str  # arithmetic, comparison, "and", "or"
    left: object
    right: object
    offset: int


@dataclasses.dataclass(frozen=True)
class Let:
    name: str
    expr: object
    offset: int


@dataclasses.dataclass(frozen=True)
class Assign:
    name: str
    expr: object
    offset: int


@dataclasses.dataclass(frozen=True)
class Print:
    expr: object
    offset: int


@dataclasses.dataclass(frozen=True)
class If:
    cond: object
    then: object
    orelse: object | None
    offset: int


@dataclasses.dataclass(frozen=True)
class While:
    cond: object
    body: object
    offset: int


@dataclasses.dataclass(frozen=True)
class Block:
    stmts: tuple
    offset: int


@dataclasses.dataclass(frozen=True)
class Module:
    stmts: tuple


_COMPARISONS = ("==", "!=", "<", "<=", ">", ">=")


class _Parser:
    def __init__(self, src: str) -> None:
        self.tokens: list[Token] = tokenize(src)
        self.pos = 0
        self.end_offset = len(src)

    # -- token helpers -------------------------------------------------
    def peek(self) -> Token | None:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def offset(self) -> int:
        tok = self.peek()
        return self.end_offset if tok is None else tok.offset

    def check(self, kind: str, text: str | None = None) -> bool:
        tok = self.peek()
        return tok is not None and tok.kind == kind and (text is None or tok.text == text)

    def advance(self) -> Token:
        tok = self.peek()
        if tok is None:
            raise ParseError("unexpected end of input", self.end_offset)
        self.pos += 1
        return tok

    def expect(self, kind: str, text: str) -> Token:
        if not self.check(kind, text):
            found = self.peek()
            what = "end of input" if found is None else repr(found.text)
            raise ParseError(f"expected {text!r} but found {what}", self.offset())
        return self.advance()

    # -- statements ----------------------------------------------------
    def parse_module(self) -> Module:
        stmts = []
        while self.peek() is not None:
            stmts.append(self.parse_statement())
        return Module(tuple(stmts))

    def parse_statement(self) -> object:
        tok = self.peek()
        if tok is None:
            raise ParseError("unexpected end of input", self.end_offset)
        if tok.kind == "KEYWORD":
            if tok.text == "let":
                return self.parse_let()
            if tok.text == "print":
                return self.parse_print()
            if tok.text == "if":
                return self.parse_if()
            if tok.text == "while":
                return self.parse_while()
            raise ParseError(f"unexpected keyword {tok.text!r}", tok.offset)
        if tok.kind == "OP" and tok.text == "{":
            return self.parse_block()
        if tok.kind == "IDENT":
            return self.parse_assign()
        raise ParseError(f"unexpected token {tok.text!r}", tok.offset)

    def parse_let(self) -> Let:
        start = self.expect("KEYWORD", "let")
        name = self.expect_ident()
        self.expect("OP", "=")
        expr = self.parse_expr()
        self.expect("OP", ";")
        return Let(name.text, expr, start.offset)

    def parse_assign(self) -> Assign:
        name = self.expect_ident()
        self.expect("OP", "=")
        expr = self.parse_expr()
        self.expect("OP", ";")
        return Assign(name.text, expr, name.offset)

    def parse_print(self) -> Print:
        start = self.expect("KEYWORD", "print")
        expr = self.parse_expr()
        self.expect("OP", ";")
        return Print(expr, start.offset)

    def parse_if(self) -> If:
        start = self.expect("KEYWORD", "if")
        self.expect("OP", "(")
        cond = self.parse_expr()
        self.expect("OP", ")")
        then = self.parse_block()
        orelse: object | None = None
        if self.check("KEYWORD", "else"):
            self.advance()
            orelse = self.parse_if() if self.check("KEYWORD", "if") else self.parse_block()
        return If(cond, then, orelse, start.offset)

    def parse_while(self) -> While:
        start = self.expect("KEYWORD", "while")
        self.expect("OP", "(")
        cond = self.parse_expr()
        self.expect("OP", ")")
        body = self.parse_block()
        return While(cond, body, start.offset)

    def parse_block(self) -> Block:
        start = self.expect("OP", "{")
        stmts = []
        while not self.check("OP", "}"):
            if self.peek() is None:
                raise ParseError("unterminated block", self.end_offset)
            stmts.append(self.parse_statement())
        self.advance()
        return Block(tuple(stmts), start.offset)

    def expect_ident(self) -> Token:
        if not self.check("IDENT"):
            raise ParseError("expected identifier", self.offset())
        return self.advance()

    # -- expressions ---------------------------------------------------
    def parse_expr(self) -> object:
        return self.parse_or()

    def parse_or(self) -> object:
        left = self.parse_and()
        while self.check("KEYWORD", "or"):
            op = self.advance()
            right = self.parse_and()
            left = Binary("or", left, right, op.offset)
        return left

    def parse_and(self) -> object:
        left = self.parse_not()
        while self.check("KEYWORD", "and"):
            op = self.advance()
            right = self.parse_not()
            left = Binary("and", left, right, op.offset)
        return left

    def parse_not(self) -> object:
        if self.check("KEYWORD", "not"):
            op = self.advance()
            return Unary("not", self.parse_not(), op.offset)
        return self.parse_comparison()

    def parse_comparison(self) -> object:
        left = self.parse_additive()
        tok = self.peek()
        if tok is not None and tok.kind == "OP" and tok.text in _COMPARISONS:
            self.advance()
            right = self.parse_additive()
            left = Binary(tok.text, left, right, tok.offset)
            again = self.peek()
            # Comparison is deliberately non-associative: 1 < 2 < 3 is rejected.
            if again is not None and again.kind == "OP" and again.text in _COMPARISONS:
                raise ParseError("comparison operators cannot be chained", again.offset)
        return left

    def parse_additive(self) -> object:
        left = self.parse_multiplicative()
        while self.check("OP", "+") or self.check("OP", "-"):
            op = self.advance()
            right = self.parse_multiplicative()
            left = Binary(op.text, left, right, op.offset)
        return left

    def parse_multiplicative(self) -> object:
        left = self.parse_unary()
        while self.check("OP", "*") or self.check("OP", "/") or self.check("OP", "%"):
            op = self.advance()
            right = self.parse_unary()
            left = Binary(op.text, left, right, op.offset)
        return left

    def parse_unary(self) -> object:
        if self.check("OP", "-"):
            op = self.advance()
            return Unary("-", self.parse_unary(), op.offset)
        return self.parse_primary()

    def parse_primary(self) -> object:
        tok = self.peek()
        if tok is None:
            raise ParseError("unexpected end of input in expression", self.end_offset)
        if tok.kind in ("INT", "FLOAT", "STRING"):
            self.advance()
            return Literal(tok.value, tok.offset)
        if tok.kind == "KEYWORD" and tok.text in ("true", "false"):
            self.advance()
            return Literal(tok.text == "true", tok.offset)
        if tok.kind == "IDENT":
            self.advance()
            return Name(tok.text, tok.offset)
        if tok.kind == "OP" and tok.text == "(":
            self.advance()
            expr = self.parse_expr()
            self.expect("OP", ")")
            return expr
        raise ParseError(f"unexpected token {tok.text!r} in expression", tok.offset)


def parse(src: str) -> object:
    """Parse ``src`` into an AST ``Module``; raises ``ParseError`` or ``LexError``."""
    return _Parser(src).parse_module()

"""Stack virtual machine and the runtime value semantics of the language."""

from __future__ import annotations

from typing import TYPE_CHECKING, Callable

from .errors import StepLimitError, VMRuntimeError
from .opcodes import OPCODES

if TYPE_CHECKING:  # avoid an import cycle: compiler -> optimizer -> vm -> compiler
    from .compiler import Program


def is_number(value: object) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def type_name(value: object) -> str:
    if isinstance(value, bool):
        return "BOOL"
    if isinstance(value, int):
        return "INT"
    if isinstance(value, float):
        return "FLOAT"
    if isinstance(value, str):
        return "STRING"
    return type(value).__name__


def render(value: object) -> str:
    if isinstance(value, bool):
        return "true" if value else "false"
    return str(value)


def _arith(op: str, left: object, right: object) -> object:
    if op == "+" and isinstance(left, str) and isinstance(right, str):
        return left + right
    if not (is_number(left) and is_number(right)):
        raise VMRuntimeError(
            f"unsupported operand types for {op}: {type_name(left)} and {type_name(right)}"
        )
    if op == "+":
        return left + right
    if op == "-":
        return left - right
    if op == "*":
        return left * right
    if op == "/":
        if right == 0:
            raise VMRuntimeError("division by zero")
        return left / right
    # op == "%"
    if not (isinstance(left, int) and isinstance(right, int)):
        raise VMRuntimeError("% requires two INT operands")
    if right == 0:
        raise VMRuntimeError("modulo by zero")
    return left % right


def _equal(left: object, right: object) -> bool:
    if is_number(left) and is_number(right):
        return left == right
    if type(left) is not type(right):
        return False
    return left == right


def _order(op: str, left: object, right: object) -> bool:
    both_numbers = is_number(left) and is_number(right)
    both_strings = isinstance(left, str) and isinstance(right, str)
    if not (both_numbers or both_strings):
        raise VMRuntimeError(
            f"cannot compare {type_name(left)} and {type_name(right)} with {op}"
        )
    if op == "<":
        return left < right
    if op == "<=":
        return left <= right
    if op == ">":
        return left > right
    return left >= right


def binary_op(op: str, left: object, right: object) -> object:
    """Apply a strict (non-short-circuit) binary operator following section 1 rules."""
    if op in ("+", "-", "*", "/", "%"):
        return _arith(op, left, right)
    if op == "==":
        return _equal(left, right)
    if op == "!=":
        return not _equal(left, right)
    if op in ("<", "<=", ">", ">="):
        return _order(op, left, right)
    raise VMRuntimeError(f"unknown binary operator {op!r}")


def unary_op(op: str, operand: object) -> object:
    if op == "-":
        if not is_number(operand):
            raise VMRuntimeError(f"unary - requires a number, got {type_name(operand)}")
        return -operand
    if op == "not":
        require_bool(operand, "not")
        return not operand
    raise VMRuntimeError(f"unknown unary operator {op!r}")


def require_bool(value: object, context: str) -> None:
    if not isinstance(value, bool):
        raise VMRuntimeError(f"{context} requires BOOL, got {type_name(value)}")


_BINARY_OPS: dict[str, str] = {
    "ADD": "+", "SUB": "-", "MUL": "*", "DIV": "/", "MOD": "%",
    "EQ": "==", "NE": "!=", "LT": "<", "LE": "<=", "GT": ">", "GE": ">=",
}
_UNSET = object()


class _Machine:
    def __init__(self, program: Program) -> None:
        self.constants = program.constants
        self.names = program.names
        self.code = program.instructions
        self.slots: list[object] = [_UNSET] * len(program.names)
        self.stack: list[object] = []
        self.output: list[str] = []
        self.ip = 0

    def pop(self) -> object:
        if not self.stack:
            raise VMRuntimeError("stack underflow")
        return self.stack.pop()

    def op_const(self, arg: int) -> None:
        self.stack.append(self.constants[arg])

    def op_load(self, arg: int) -> None:
        value = self.slots[arg]
        if value is _UNSET:
            raise VMRuntimeError(f"variable {self.names[arg]!r} read before assignment")
        self.stack.append(value)

    def op_store(self, arg: int) -> None:
        self.slots[arg] = self.pop()

    def op_jump(self, arg: int) -> None:
        self.ip = arg

    def op_jump_if_false(self, arg: int) -> None:
        cond = self.pop()
        require_bool(cond, "condition")
        if not cond:
            self.ip = arg

    def op_print(self, arg: int) -> None:
        self.output.append(render(self.pop()))

    def op_pop(self, arg: int) -> None:
        self.pop()

    def op_neg(self, arg: int) -> None:
        self.stack.append(unary_op("-", self.pop()))

    def op_not(self, arg: int) -> None:
        self.stack.append(unary_op("not", self.pop()))

    def op_binary(self, opname: str) -> None:
        right = self.pop()
        left = self.pop()
        self.stack.append(binary_op(_BINARY_OPS[opname], left, right))

    def run(self, step_limit: int) -> list[str]:
        handlers: dict[str, Callable[[int], None]] = {
            "CONST": self.op_const, "LOAD": self.op_load, "STORE": self.op_store,
            "JUMP": self.op_jump, "JUMP_IF_FALSE": self.op_jump_if_false,
            "PRINT": self.op_print, "POP": self.op_pop,
            "NEG": self.op_neg, "NOT": self.op_not,
        }
        steps = 0
        code = self.code
        while True:
            if self.ip < 0 or self.ip >= len(code):
                raise VMRuntimeError(f"instruction pointer {self.ip} out of range")
            instr = code[self.ip]
            self.ip += 1
            steps += 1
            if steps > step_limit:
                raise StepLimitError(f"step limit of {step_limit} exceeded")
            op = instr.op
            if op == "HALT":
                return self.output
            if op in _BINARY_OPS:
                self.op_binary(op)
            elif op in handlers:
                handlers[op](instr.arg)  # type: ignore[arg-type]
            elif op in OPCODES:
                raise VMRuntimeError(f"unhandled opcode {op}")
            else:
                raise VMRuntimeError(f"unknown opcode {op!r}")


def execute(program: Program, *, step_limit: int = 100_000) -> list[str]:
    """Run ``program`` and return its printed lines."""
    if isinstance(step_limit, bool) or not isinstance(step_limit, int) or step_limit <= 0:
        raise ValueError("step_limit must be a positive int")
    return _Machine(program).run(step_limit)

