"""Behaviour-preserving constant folding over the AST."""

from __future__ import annotations

import dataclasses

from . import parser as ast
from .errors import VMRuntimeError
from .vm import binary_op, unary_op


def _is_literal(node: object) -> bool:
    return isinstance(node, ast.Literal)


def _is_bool_literal(node: object) -> bool:
    return isinstance(node, ast.Literal) and isinstance(node.value, bool)


def _fold_logical(node: ast.Binary) -> object:
    left, right = node.left, node.right
    if _is_bool_literal(left) and _is_bool_literal(right):
        result = (left.value and right.value) if node.op == "and" else (left.value or right.value)
        return ast.Literal(bool(result), node.offset)
    # The right operand is never evaluated in these two cases, so dropping it is safe.
    if node.op == "and" and _is_bool_literal(left) and left.value is False:
        return ast.Literal(False, node.offset)
    if node.op == "or" and _is_bool_literal(left) and left.value is True:
        return ast.Literal(True, node.offset)
    # `true and X` / `false or X` keep the runtime BOOL check on X: do not fold.
    return node


def _fold_binary(node: ast.Binary) -> object:
    if node.op in ("and", "or"):
        return _fold_logical(node)
    if not (_is_literal(node.left) and _is_literal(node.right)):
        return node
    try:
        value = binary_op(node.op, node.left.value, node.right.value)
    except VMRuntimeError:
        return node  # would fail at run time; keep it so it still fails there
    return ast.Literal(value, node.offset)


def _fold_unary(node: ast.Unary) -> object:
    if not _is_literal(node.operand):
        return node
    try:
        value = unary_op(node.op, node.operand.value)
    except VMRuntimeError:
        return node
    return ast.Literal(value, node.offset)


def fold_constants(node: object) -> object:
    """Return an equivalent AST with literal-only sub-expressions pre-evaluated."""
    if isinstance(node, ast.Binary):
        folded = ast.Binary(
            node.op, fold_constants(node.left), fold_constants(node.right), node.offset
        )
        return _fold_binary(folded)
    if isinstance(node, ast.Unary):
        return _fold_unary(ast.Unary(node.op, fold_constants(node.operand), node.offset))
    if isinstance(node, (ast.Literal, ast.Name)):
        return node
    if isinstance(node, (ast.Let, ast.Assign, ast.Print)):
        return dataclasses.replace(node, expr=fold_constants(node.expr))
    if isinstance(node, ast.If):
        orelse = None if node.orelse is None else fold_constants(node.orelse)
        return ast.If(
            fold_constants(node.cond), fold_constants(node.then), orelse, node.offset
        )
    if isinstance(node, ast.While):
        return ast.While(fold_constants(node.cond), fold_constants(node.body), node.offset)
    if isinstance(node, ast.Block):
        return ast.Block(tuple(fold_constants(s) for s in node.stmts), node.offset)
    if isinstance(node, ast.Module):
        return ast.Module(tuple(fold_constants(s) for s in node.stmts))
    return node

"""Checksummed binary encoding of compiled programs."""

from __future__ import annotations

import struct
import zlib

from .compiler import Instr, Program
from .errors import SerializationError
from .opcodes import OPCODES, OPCODE_NUMBERS, OPCODES_WITH_ARG

MAGIC = b"MVM1"
VERSION = 1
NO_ARG = 0xFFFFFFFF
_INT_MIN = -(1 << 63)
_INT_MAX = (1 << 63) - 1
_TAG_INT, _TAG_FLOAT, _TAG_STRING, _TAG_BOOL = 1, 2, 3, 4


def _u16(value: int, what: str) -> bytes:
    if not 0 <= value <= 0xFFFF:
        raise SerializationError(f"{what} {value} does not fit in u16")
    return struct.pack(">H", value)


def _u32(value: int, what: str) -> bytes:
    if not 0 <= value <= 0xFFFFFFFF:
        raise SerializationError(f"{what} {value} does not fit in u32")
    return struct.pack(">I", value)


def _encode_constant(value: object) -> bytes:
    if isinstance(value, bool):
        return bytes([_TAG_BOOL, 1 if value else 0])
    if isinstance(value, int):
        if not _INT_MIN <= value <= _INT_MAX:
            raise SerializationError(f"INT constant {value} is outside the signed 64-bit range")
        return bytes([_TAG_INT]) + struct.pack(">q", value)
    if isinstance(value, float):
        return bytes([_TAG_FLOAT]) + struct.pack(">d", value)
    if isinstance(value, str):
        payload = value.encode("utf-8")
        return bytes([_TAG_STRING]) + _u32(len(payload), "string length") + payload
    raise SerializationError(f"unsupported constant type {type(value).__name__}")


def _encode_instr(instr: Instr) -> bytes:
    number = OPCODE_NUMBERS.get(instr.op)
    if number is None:
        raise SerializationError(f"unknown opcode {instr.op!r}")
    takes_arg = instr.op in OPCODES_WITH_ARG
    if takes_arg:
        if not isinstance(instr.arg, int) or isinstance(instr.arg, bool):
            raise SerializationError(f"opcode {instr.op} requires an int argument")
        if not 0 <= instr.arg < NO_ARG:
            raise SerializationError(f"argument {instr.arg} of {instr.op} is out of range")
        arg = instr.arg
    else:
        if instr.arg is not None:
            raise SerializationError(f"opcode {instr.op} takes no argument")
        arg = NO_ARG
    return bytes([number]) + struct.pack(">I", arg)


def dumps(program: Program) -> bytes:
    body = bytearray()
    body.append(VERSION)
    body += _u16(len(program.names), "name count")
    for name in program.names:
        if not isinstance(name, str):
            raise SerializationError("variable names must be strings")
        raw = name.encode("utf-8")
        body += _u16(len(raw), "name length") + raw
    body += _u16(len(program.constants), "constant count")
    for value in program.constants:
        body += _encode_constant(value)
    body += _u32(len(program.instructions), "instruction count")
    for instr in program.instructions:
        body += _encode_instr(instr)
    checksum = zlib.crc32(bytes(body)) & 0xFFFFFFFF
    return MAGIC + bytes(body) + struct.pack(">I", checksum)


class _Reader:
    def __init__(self, data: bytes) -> None:
        self.data = data
        self.pos = 0

    def take(self, count: int, what: str) -> bytes:
        if count < 0 or self.pos + count > len(self.data):
            raise SerializationError(f"truncated data while reading {what}")
        chunk = self.data[self.pos:self.pos + count]
        self.pos += count
        return chunk

    def unpack(self, fmt: str, what: str) -> int:
        return struct.unpack(fmt, self.take(struct.calcsize(fmt), what))[0]

    def utf8(self, length: int, what: str) -> str:
        try:
            return self.take(length, what).decode("utf-8")
        except UnicodeDecodeError as exc:
            raise SerializationError(f"invalid UTF-8 in {what}") from exc

    def constant(self) -> object:
        tag = self.unpack(">B", "constant tag")
        if tag == _TAG_INT:
            return self.unpack(">q", "INT constant")
        if tag == _TAG_FLOAT:
            return struct.unpack(">d", self.take(8, "FLOAT constant"))[0]
        if tag == _TAG_STRING:
            return self.utf8(self.unpack(">I", "string length"), "STRING constant")
        if tag == _TAG_BOOL:
            raw = self.unpack(">B", "BOOL constant")
            if raw not in (0, 1):
                raise SerializationError(f"invalid BOOL payload {raw}")
            return raw == 1
        raise SerializationError(f"unknown constant tag {tag}")

    def instr(self) -> Instr:
        number = self.unpack(">B", "opcode")
        arg = self.unpack(">I", "instruction argument")
        if not 1 <= number <= len(OPCODES):
            raise SerializationError(f"unknown opcode number {number}")
        op = OPCODES[number - 1]
        if op in OPCODES_WITH_ARG:
            if arg == NO_ARG:
                raise SerializationError(f"opcode {op} is missing its argument")
            return Instr(op, arg)
        if arg != NO_ARG:
            raise SerializationError(f"opcode {op} takes no argument but has {arg}")
        return Instr(op, None)


def loads(data: bytes) -> Program:
    if not isinstance(data, (bytes, bytearray)):
        raise SerializationError("expected bytes")
    data = bytes(data)
    if len(data) < len(MAGIC) + 4:
        raise SerializationError("data too short")
    if data[:4] != MAGIC:
        raise SerializationError("bad magic")
    body, (expected,) = data[4:-4], struct.unpack(">I", data[-4:])
    # The checksum guards every length field: validate it before decoding anything.
    if zlib.crc32(body) & 0xFFFFFFFF != expected:
        raise SerializationError("checksum mismatch")
    reader = _Reader(body)
    version = reader.unpack(">B", "version")
    if version != VERSION:
        raise SerializationError(f"unsupported version {version}")
    names = [
        reader.utf8(reader.unpack(">H", "name length"), "name")
        for _ in range(reader.unpack(">H", "name count"))
    ]
    constants = [reader.constant() for _ in range(reader.unpack(">H", "constant count"))]
    instructions = [reader.instr() for _ in range(reader.unpack(">I", "instruction count"))]
    if reader.pos != len(body):
        raise SerializationError("trailing bytes after program body")
    return Program(constants, names, instructions)

"""Human-readable listing of a compiled program."""

from __future__ import annotations

from .compiler import Program
from .vm import render

_STRING_ESCAPES: dict[str, str] = {"\\": "\\\\", '"': '\\"', "\n": "\\n", "\t": "\\t"}


def render_constant(value: object) -> str:
    if isinstance(value, str):
        return '"' + "".join(_STRING_ESCAPES.get(ch, ch) for ch in value) + '"'
    return render(value)


def disassemble(program: Program) -> str:
    lines: list[str] = []
    for index, instr in enumerate(program.instructions):
        line = f"{index:04d} {instr.op}"
        if instr.arg is not None:
            line += f" {instr.arg}"
        if instr.op == "CONST":
            line += f"  ; {render_constant(program.constants[instr.arg])}"
        lines.append(line + "\n")
    return "".join(lines)

"""Command-line interface: ``python -m microvm COMMAND ...``."""

from __future__ import annotations

import argparse
import sys

from .compiler import Program, compile_source
from .disassembler import disassemble
from .errors import MicroVMError
from .serializer import dumps, loads
from .vm import execute

EXIT_OK = 0
EXIT_USAGE = 2
EXIT_ERROR = 3


class _UsageError(Exception):
    """Raised for I/O problems that count as usage errors (exit code 2)."""


def _positive_int(text: str) -> int:
    try:
        value = int(text)
    except ValueError:
        raise argparse.ArgumentTypeError(f"invalid positive integer {text!r}") from None
    if value <= 0:
        raise argparse.ArgumentTypeError(f"step limit must be positive, got {value}")
    return value


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="microvm", description="microvm toolchain")
    sub = parser.add_subparsers(dest="command", required=True)

    run = sub.add_parser("run", help="compile a source file and execute it")
    run.add_argument("file")
    run.add_argument("--optimize", action="store_true")
    run.add_argument("--step-limit", type=_positive_int, default=100_000)

    build = sub.add_parser("build", help="compile a source file to a binary")
    build.add_argument("file")
    build.add_argument("out")
    build.add_argument("--optimize", action="store_true")

    exe = sub.add_parser("exec", help="execute a compiled binary")
    exe.add_argument("file")
    exe.add_argument("--step-limit", type=_positive_int, default=100_000)

    disasm = sub.add_parser("disasm", help="disassemble a compiled binary")
    disasm.add_argument("file")
    return parser


def _read_text(path: str) -> str:
    try:
        with open(path, "r", encoding="utf-8") as handle:
            return handle.read()
    except (OSError, UnicodeDecodeError) as exc:
        raise _UsageError(f"cannot read {path}: {exc}") from exc


def _read_bytes(path: str) -> bytes:
    try:
        with open(path, "rb") as handle:
            return handle.read()
    except OSError as exc:
        raise _UsageError(f"cannot read {path}: {exc}") from exc


def _write_bytes(path: str, data: bytes) -> None:
    try:
        with open(path, "wb") as handle:
            handle.write(data)
    except OSError as exc:
        raise _UsageError(f"cannot write {path}: {exc}") from exc


def _dispatch(args: argparse.Namespace) -> str:
    """Perform the command and return the full stdout text (printed only on success)."""
    if args.command == "run":
        program = compile_source(_read_text(args.file), optimize=args.optimize)
        return "".join(line + "\n" for line in execute(program, step_limit=args.step_limit))
    if args.command == "build":
        program = compile_source(_read_text(args.file), optimize=args.optimize)
        _write_bytes(args.out, dumps(program))
        return ""
    if args.command == "exec":
        program: Program = loads(_read_bytes(args.file))
        return "".join(line + "\n" for line in execute(program, step_limit=args.step_limit))
    if args.command == "disasm":
        return disassemble(loads(_read_bytes(args.file)))
    raise _UsageError(f"unknown command {args.command!r}")


def main(argv: list[str] | None = None) -> int:
    parser = _build_parser()
    try:
        args = parser.parse_args(argv)
    except SystemExit as exc:  # argparse already printed its message
        code = exc.code
        return code if isinstance(code, int) else EXIT_USAGE
    try:
        output = _dispatch(args)
    except _UsageError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return EXIT_USAGE
    except MicroVMError as exc:
        print(f"error: {type(exc).__name__}: {exc}", file=sys.stderr)
        return EXIT_ERROR
    sys.stdout.write(output)
    sys.stdout.flush()
    return EXIT_OK


if __name__ == "__main__":
    sys.exit(main())

